-- Provisional presentation parameters match existing deliberately paced infantry.
-- Coordinator still measures all effects, sound, native accuracy and collision.
for _,d in pairs(M.Definitions)do
 for _,w in pairs(d.weapondefs or {})do
  if w.weapontype~="Melee" then
   w.accuracy=w.weapontype=="BeamLaser" and 120 or (w.burst and 450 or 180)
   w.targetmoveerror=.15
  end
 end
end
local function accepted(ready,name)
 if type(ready)=="function" then return ready(name)==true end
 return type(ready)=="table" and ready[name]==true
end
function M.Apply(defs,ready)
 local count=0
 for name,definition in pairs(M.Definitions) do
  if accepted(ready,name) and VFS.FileExists("objects3d/"..name..".glb")
   and VFS.FileExists("scripts/generated/"..name.."_anim.lua") and VFS.FileExists("scripts/40k_roster.lua") then
   -- Every invocation receives an independent copy; shared authored templates stay immutable.
   local function copy(v)if type(v)~="table" then return v end;local out={};for k,item in pairs(v)do out[k]=copy(item)end;return out end
   defs[name]=copy(definition);count=count+1
  end
 end
 return count
end
VFS.Include('40k_configs/ork_retired_content_policy.lua').FilterDefinitions(M.Definitions)
return M
